"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97934"],{9685(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio","status":422,"titulo":"O n\xfamero de inscri\xe7\xe3o \xe9 o piso da divulga\xe7\xe3o p\xfablica e n\xe3o pode ser removido"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio","requisitos":[],"oQueAconteceu":["O n\xfamero de inscri\xe7\xe3o \xe9 o piso da divulga\xe7\xe3o p\xfablica: \xe9 o \xfanico campo do padr\xe3o minimizado e est\xe1\\nsempre presente, qualquer que seja a amplia\xe7\xe3o configurada. A lista `camposPublicos` enviada tem\\nitens, mas n\xe3o inclui `NUMERO_INSCRICAO`.","Esta confer\xeancia s\xf3 vale com a lista n\xe3o vazia; a lista vazia \xe9 outra causa\\n([`campos_publicos_vazio`](/erros/uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio)). A\\nrecusa vem junto das demais viola\xe7\xf5es do mesmo pedido, no array `errors[]`, e pode aparecer ao\\nlado de\\n[`campo_nao_permitido`](/erros/uniplus.selecao.configuracao_divulgacao.campo_nao_permitido), de\\n[`formas_de_identificacao_excludentes`](/erros/uniplus.selecao.configuracao_divulgacao.formas_de_identificacao_excludentes)\\ne das recusas da justificativa.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz uma lista sem o n\xfamero de\\ninscri\xe7\xe3o, porque a defini\xe7\xe3o a recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica,\\nsem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Inclua `NUMERO_INSCRICAO` em `camposPublicos`. Se a inten\xe7\xe3o era voltar ao padr\xe3o minimizado,\\nenvie `camposPublicos` nulo em vez de uma lista sem o n\xfamero de inscri\xe7\xe3o: o nulo remove a\\nconfigura\xe7\xe3o expl\xedcita e o processo volta a divulgar s\xf3 o n\xfamero de inscri\xe7\xe3o.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a divulga\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);